export function setLanguage(value){language=['en','fr','sw'].includes(value)?value:'en';return language;}
export function getLanguage(){return language;}
export function t(text){return translations[language]?.[text]??text;}
export function displayValue(value){if(Array.isArray(value))return value.map(item=>typeof item==='object'?JSON.stringify(item):String(item)).join('\n');return typeof value==='object'?JSON.stringify(value):String(value??'—');}

