Object.assign(translations.sw,{"Closure check": "Ukaguzi wa kufunga", "Account closure check": "Ukaguzi wa kufunga akaunti", "Posted": "Iliyorekodiwa", "Held": "Iliyozuiwa", "Ledger balance": "Salio la leja", "Closure preserves history and does not pay out balances or settle interest, fees, contracts or payment returns.": "Kufunga huhifadhi historia. Hakulipi salio wala kusuluhisha riba, ada, mikataba au marejesho ya malipo.", "Release all account holds before closure.": "Ondoa vizuizi vyote vya fedha kabla ya kufunga."});

Object.assign(translations.fr,{"Closure requires zero customer and ledger balances. Funded accounts cannot return to awaiting funding.": "La clôture exige des soldes client et comptable nuls. Un compte déjà approvisionné ne peut pas revenir en attente de financement.", "Closure is blocked for linked contracts until a final contract settlement workflow is available.": "Les contrats liés empêchent la clôture tant que leur règlement final n’est pas pris en charge.", "Closure is blocked for payment history until late returns and settlement obligations can be handled.": "L’historique de paiements empêche la clôture tant que les retours tardifs et obligations de règlement ne sont pas pris en charge.", "Final interest and fee settlement is required. Closure for serviced accounts is not yet supported.": "Le règlement final des intérêts et frais est requis. La clôture de ces comptes n’est pas encore prise en charge.", "The original maker and approver must both be active before first delivery.": "Le créateur et l’approbateur d’origine doivent tous deux être actifs avant la première exécution."});

Object.assign(translations.sw,{"Closure requires zero customer and ledger balances. Funded accounts cannot return to awaiting funding.": "Kufunga kunahitaji salio la mteja na la leja kuwa sifuri. Akaunti iliyofadhiliwa haiwezi kurudi kusubiri ufadhili.", "Closure is blocked for linked contracts until a final contract settlement workflow is available.": "Mikataba iliyounganishwa inazuia kufunga hadi utaratibu wa malipo ya mwisho upatikane.", "Closure is blocked for payment history until late returns and settlement obligations can be handled.": "Historia ya malipo inazuia kufunga hadi marejesho ya kuchelewa na wajibu wa malipo uweze kushughulikiwa.", "Final interest and fee settlement is required. Closure for serviced accounts is not yet supported.": "Malipo ya mwisho ya riba na ada yanahitajika. Kufunga akaunti hizi bado hakutumiki.", "The original maker and approver must both be active before first delivery.": "Mwanzilishi na mwidhinishaji wa awali lazima wote wawe hai kabla ya utekelezaji wa kwanza."});
// Final closure settlement (W03). Machine-assisted wording; include in the pending language review.
Object.assign(translations.fr,{"Final settlement before closure":"Règlement final avant clôture","Final settlement prerequisites":"Prérequis du règlement final","Final closure settlement":"Règlement final de clôture","Approve an asset ledger in the account currency and legal entity to pay out the final balance.":"Approuvez un compte d’actif dans la devise et l’entité juridique du compte pour verser le solde final.","Residual interest below the smallest currency unit is forfeited:":"Intérêts résiduels inférieurs à la plus petite unité monétaire abandonnés :","Pays out the whole posted balance, including the product minimum, and freezes the account until closure is approved. Interest is settled through the last completed daily processing run. Release holds first.":"Verse la totalité du solde comptabilisé, minimum du produit compris, et bloque le compte jusqu’à l’approbation de la clôture. Les intérêts sont réglés jusqu’au dernier traitement quotidien terminé. Levez d’abord les blocages.","Closure preserves history. Pay out any remaining balance through final settlement first; contracts and payment returns are not settled here.":"La clôture conserve l’historique. Versez d’abord tout solde restant par un règlement final ; les contrats et les retours de paiement ne sont pas réglés ici.","Residual interest carry remains. Approve a final settlement to record it as forfeited before closure.":"Un reliquat d’intérêts subsiste. Approuvez un règlement final pour l’enregistrer comme abandonné avant la clôture.","This account has a final settlement and only accepts the closure request now.":"Ce compte a un règlement final et n’accepte plus que la demande de clôture.","Final settlement must pay out the whole posted balance with no holds. Refresh the closure check and resubmit.":"Le règlement final doit verser la totalité du solde comptabilisé, sans blocage. Actualisez la vérification de clôture et soumettez à nouveau.","The account balance is already zero; submit the closure directly.":"Le solde du compte est déjà nul ; soumettez directement la clôture.","Complete the running daily processing batch before final settlement or closure.":"Terminez le traitement quotidien en cours avant le règlement final ou la clôture."});
Object.assign(translations.sw,{"Final settlement before closure":"Malipo ya mwisho kabla ya kufunga","Final settlement prerequisites":"Mahitaji ya malipo ya mwisho","Final closure settlement":"Malipo ya mwisho ya kufunga","Approve an asset ledger in the account currency and legal entity to pay out the final balance.":"Idhinisha leja ya mali katika sarafu na taasisi ya akaunti ili kulipa salio la mwisho.","Residual interest below the smallest currency unit is forfeited:":"Riba iliyobaki chini ya kipimo kidogo cha sarafu inaachwa:","Pays out the whole posted balance, including the product minimum, and freezes the account until closure is approved. Interest is settled through the last completed daily processing run. Release holds first.":"Hulipa salio lote lililorekodiwa, pamoja na kiwango cha chini cha bidhaa, na kuzuia akaunti hadi kufunga kuidhinishwe. Riba hulipwa hadi uchakataji wa kila siku uliokamilika mwisho. Ondoa vizuizi kwanza.","Closure preserves history. Pay out any remaining balance through final settlement first; contracts and payment returns are not settled here.":"Kufunga huhifadhi historia. Lipa salio lolote lililobaki kwa malipo ya mwisho kwanza; mikataba na marejesho ya malipo hayashughulikiwi hapa.","Residual interest carry remains. Approve a final settlement to record it as forfeited before closure.":"Kuna riba iliyobaki. Idhinisha malipo ya mwisho ili irekodiwe kuwa imeachwa kabla ya kufunga.","This account has a final settlement and only accepts the closure request now.":"Akaunti hii ina malipo ya mwisho na sasa inakubali ombi la kufunga pekee.","Final settlement must pay out the whole posted balance with no holds. Refresh the closure check and resubmit.":"Malipo ya mwisho lazima yalipe salio lote lililorekodiwa bila vizuizi. Onyesha upya ukaguzi wa kufunga na uwasilishe tena.","The account balance is already zero; submit the closure directly.":"Salio la akaunti tayari ni sifuri; wasilisha ombi la kufunga moja kwa moja.","Complete the running daily processing batch before final settlement or closure.":"Kamilisha uchakataji wa kila siku unaoendelea kabla ya malipo ya mwisho au kufunga."});
